<section class="page-head profile-head"><div class="profile-hero"><?php $ph=$profile['photo']??'';?><div class="profile-photo"><?php if($ph):?><img src="<?=$config['base_url'].'/'.$ph?>" alt="Profile"><?php else:?><span><?=htmlspecialchars(strtoupper(substr($profile['name'],0,1)))?></span><?php endif?></div><div><span class="eyebrow"><?=strtoupper(str_replace('_',' ',$profile['role_name']))?> PROFILE</span><h1><?=htmlspecialchars($profile['name'])?></h1><p><?=htmlspecialchars($profile['email'])?> • <?=htmlspecialchars($profile['phone'])?></p></div><?php if(in_array($profile['role_name'],['patient','doctor'])):?><a class="btn primary" href="<?=$config['base_url']?>/profile/edit">Edit Profile</a><?php endif?></div></section>
<section class="profile-grid"><article class="form-card"><h3>Personal Information</h3><div class="detail-grid"><div><small>Full Name</small><b><?=htmlspecialchars($profile['name'])?></b></div><div><small>Phone</small><b><?=htmlspecialchars($profile['phone'])?></b></div><div><small>Email</small><b><?=htmlspecialchars($profile['email'])?></b></div><div><small>Aadhaar</small><b><?=htmlspecialchars($profile['aadhaar_no']??'—')?></b></div><div><small>PAN</small><b><?=htmlspecialchars($profile['pan_no']??'—')?></b></div><div><small>Status</small><b><?=htmlspecialchars(ucfirst($profile['status']))?></b></div></div></article><article class="form-card"><h3>Address</h3><p><?=htmlspecialchars($profile['address_line1']??'')?> <?=htmlspecialchars($profile['address_line2']??'')?><br><?=htmlspecialchars($profile['city']??'')?>, <?=htmlspecialchars($profile['state']??'')?> - <?=htmlspecialchars($profile['pincode']??'')?><br><?=htmlspecialchars($profile['country']??'India')?></p></article><?php if($doctor):?><article class="form-card"><h3>Professional Information</h3><div class="detail-grid"><div><small>Specialization</small><b><?=htmlspecialchars($doctor['specialization_name']??'—')?></b></div><div><small>Medical Registration</small><b><?=htmlspecialchars($doctor['medical_registration_no'])?></b></div><div><small>Council</small><b><?=htmlspecialchars($doctor['registration_council'])?></b></div><div><small>Experience</small><b><?=intval($doctor['experience_years'])?> Years</b></div><div><small>Verification</small><b><?=htmlspecialchars(ucfirst($doctor['verification_status']))?></b></div></div><p><?=htmlspecialchars($doctor['bio']??'')?></p></article><?php endif?></section>
